// parseSinceDays parses a duration string like "7d" or "30d" and returns the number of days.
func parseSinceDays(since string) (int, error) {
	s := strings.TrimSpace(since)
	s = strings.TrimSuffix(s, "d")
	s = strings.TrimSuffix(s, "h")
	n, err := strconv.Atoi(s)
	if err != nil {
		return 7, nil // default to 7 days
	}
	if n <= 0 {
		return 7, nil
	}
	return n, nil
}

// extractKeywordRankChanges parses the history API response and returns rank changes per keyword.
// The AppTweak history endpoint typically returns:
//
//	{"content": {"<keyword>": [{"date": "2026-05-21", "rank": 8}, ...]}}
func extractKeywordRankChanges(data json.RawMessage) []keywordRankChange {
	var changes []keywordRankChange

	// Try top-level object with "content", "data", or "results" key
	var top map[string]json.RawMessage
	if err := json.Unmarshal(data, &top); err != nil {
		return changes
	}

	var contentRaw json.RawMessage
	for _, key := range []string{"content", "data", "results"} {
		if raw, ok := top[key]; ok {
			contentRaw = raw
			break
		}
	}
	if contentRaw == nil {
		contentRaw = data
	}

	// Try map[keyword] -> []history entries
	var kwMap map[string]json.RawMessage
	if err := json.Unmarshal(contentRaw, &kwMap); err == nil {
		for kw, histRaw := range kwMap {
			var history []map[string]json.RawMessage
			if err := json.Unmarshal(histRaw, &history); err != nil || len(history) == 0 {
				continue
			}

			first := extractRankFromEntry(history[0])
			last := extractRankFromEntry(history[len(history)-1])

			delta := last - first
			trend := "flat"
			if last < first {
				trend = "up" // lower rank number = better position
			} else if last > first {
				trend = "down"
			}

			changes = append(changes, keywordRankChange{
				Keyword:   kw,
				RankStart: first,
				RankEnd:   last,
				Delta:     delta,
				Trend:     trend,
			})
		}
		return changes
	}

	// Fallback: try array of {keyword, rank} objects (flat format)
	var arr []map[string]json.RawMessage
	if err := json.Unmarshal(contentRaw, &arr); err == nil {
		for _, item := range arr {
			var kw string
			var rank int
			if kwRaw, ok := item["keyword"]; ok {
				_ = json.Unmarshal(kwRaw, &kw)
			}
			if rankRaw, ok := item["rank"]; ok {
				_ = json.Unmarshal(rankRaw, &rank)
			}
			if kw != "" {
				changes = append(changes, keywordRankChange{
					Keyword:   kw,
					RankStart: rank,
					RankEnd:   rank,
					Delta:     0,
					Trend:     "flat",
				})
			}
		}
	}

	return changes
}

// extractRankFromEntry extracts the rank integer from a history entry like {"date": "...", "rank": 8}.
func extractRankFromEntry(entry map[string]json.RawMessage) int {
	for _, key := range []string{"rank", "position", "ranking"} {
		if raw, ok := entry[key]; ok {
			var rank int
			if json.Unmarshal(raw, &rank) == nil {
				return rank
			}
		}
	}
	return 0
}
